WITH RECURSIVE seq(n) AS (SELECT 10 UNION ALL SELECT n+1 FROM seq WHERE n<2*(SELECT count(*)+50 FROM commercial_catalog_codes)), free AS (SELECT n FROM seq WHERE NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE accounting_code='AVS'||printf('%03d',n) OR sku='AVY-SRV-GEN-'||printf('%03d',n)) ORDER BY n LIMIT 1)
