SELECT 'catalog_0117_studio_'||p.id,'service','studio-plan-'||p.id,p.name,CASE WHEN NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE sku='AVY-PLAN-PRO' AND NOT(entity_type='service' AND entity_key='studio-plan-pro')) THEN 'AVY-PLAN-PRO' ELSE 'AVY-SRV-GEN-'||printf('%03d',n) END,'AVS'||printf('%03d',n),'studio-plan',p.price_ron_cents,'RON',0,'unconfigured','needs_configuration',1,'',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'plan','fixed','annual','unverified' FROM free JOIN partnership_plans p ON p.id='pro' WHERE 1 ON CONFLICT(entity_type,entity_key) DO UPDATE SET sku=CASE WHEN NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL THEN excluded.sku ELSE commercial_catalog_codes.sku END,accounting_code=CASE WHEN NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL THEN excluded.accounting_code ELSE commercial_catalog_codes.accounting_code END,updated_at=excluded.updated_at WHERE NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL OR NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL;
