SELECT 'catalog_0117_service_'||'sub-app-pro','service','sub-app-pro','Mentenanță Aplicație web/mobile — Pro',CASE WHEN NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE sku='sub-app-pro' AND NOT(entity_type='service' AND entity_key='sub-app-pro')) THEN 'sub-app-pro' ELSE 'AVY-SRV-GEN-'||printf('%03d',n) END,'AVS'||printf('%03d',n),'maintenance',100000,'RON',0,'unconfigured','needs_configuration',1,'',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'serviciu','fixed','monthly','unverified' FROM free WHERE 1 ON CONFLICT(entity_type,entity_key) DO UPDATE SET sku=CASE WHEN NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL THEN excluded.sku ELSE commercial_catalog_codes.sku END,accounting_code=CASE WHEN NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL THEN excluded.accounting_code ELSE commercial_catalog_codes.accounting_code END,updated_at=excluded.updated_at WHERE NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL OR NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL;
