SELECT 'catalog_0117_service_'||'sub-app-proactiv','service','sub-app-proactiv','Mentenanță Aplicație web/mobile — Pro Activ',CASE WHEN NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE sku='sub-app-proactiv' AND NOT(entity_type='service' AND entity_key='sub-app-proactiv')) THEN 'sub-app-proactiv' ELSE 'AVY-SRV-GEN-'||printf('%03d',n) END,'AVS'||printf('%03d',n),'maintenance',150000,'RON',0,'unconfigured','needs_configuration',1,'',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'serviciu','fixed','monthly','unverified' FROM free WHERE 1 ON CONFLICT(entity_type,entity_key) DO UPDATE SET sku=CASE WHEN NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL THEN excluded.sku ELSE commercial_catalog_codes.sku END,accounting_code=CASE WHEN NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL THEN excluded.accounting_code ELSE commercial_catalog_codes.accounting_code END,updated_at=excluded.updated_at WHERE NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL OR NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL;
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<2*((SELECT count(*) FROM commercial_catalog_codes)+(SELECT count(*) FROM product_items))+32),
free AS (SELECT n,row_number() OVER(ORDER BY n) rn FROM seq WHERE NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE accounting_code='AVD'||printf('%04d',n) OR sku GLOB 'AVY-DIG-*-'||printf('%04d',n))),
missing AS (SELECT p.*,c.id existing_id,c.sku existing_sku,c.accounting_code existing_article,row_number() OVER(ORDER BY p.slug) rn FROM product_items p LEFT JOIN commercial_catalog_codes c ON c.entity_type='product' AND c.entity_key=p.slug WHERE NULLIF(trim(c.sku),'') IS NULL OR NULLIF(trim(c.accounting_code),'') IS NULL)
INSERT INTO commercial_catalog_codes(id,entity_type,entity_key,display_name,sku,accounting_code,category,base_price_minor,currency,vat_basis_points,payment_route,payment_status,active,notes,created_at,updated_at,unit_label,price_model,billing_cycle,tax_status)
SELECT COALESCE(existing_id,'catalog_0117_product_'||slug),'product',slug,name_ro,COALESCE(CASE WHEN NULLIF(trim(existing_sku),'') IS NOT NULL THEN existing_sku END,'AVY-DIG-'||CASE type WHEN 'component' THEN 'CMP' WHEN 'section' THEN 'SEC' WHEN 'template' THEN 'TPL' WHEN 'effect' THEN '3DE' WHEN 'tool' THEN 'TOL' WHEN 'api' THEN 'API' WHEN 'doc' THEN 'DOC' WHEN 'logo' THEN 'LGO' ELSE 'GEN' END||'-'||printf('%04d',n)),COALESCE(CASE WHEN NULLIF(trim(existing_article),'') IS NOT NULL THEN existing_article END,'AVD'||printf('%04d',n)),type,price_ron_cents,'RON',0,'unconfigured','needs_configuration',CASE WHEN status='live' THEN 1 ELSE 0 END,'',CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'unitate',CASE WHEN price_ron_cents IS NULL THEN 'unreviewed' ELSE 'fixed' END,'unreviewed','unverified' FROM missing JOIN free USING(rn) WHERE 1 ON CONFLICT(entity_type,entity_key) DO UPDATE SET sku=CASE WHEN NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL THEN excluded.sku ELSE commercial_catalog_codes.sku END,accounting_code=CASE WHEN NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL THEN excluded.accounting_code ELSE commercial_catalog_codes.accounting_code END,updated_at=excluded.updated_at WHERE NULLIF(trim(commercial_catalog_codes.sku),'') IS NULL OR NULLIF(trim(commercial_catalog_codes.accounting_code),'') IS NULL;
WITH RECURSIVE seq(n) AS (SELECT 10 UNION ALL SELECT n+1 FROM seq WHERE n<2*(SELECT count(*)+50 FROM commercial_catalog_codes)), free AS (SELECT n,row_number() OVER(ORDER BY n) rn FROM seq WHERE NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE accounting_code='AVS'||printf('%03d',n) OR sku GLOB 'AVY-SRV-*-'||printf('%03d',n))), missing AS (SELECT id,row_number() OVER(ORDER BY entity_key) rn FROM commercial_catalog_codes WHERE entity_type='service' AND (NULLIF(trim(sku),'') IS NULL OR NULLIF(trim(accounting_code),'') IS NULL)), allocation AS MATERIALIZED (SELECT missing.id,free.n FROM missing JOIN free USING(rn))
UPDATE commercial_catalog_codes SET sku=CASE WHEN NULLIF(trim(sku),'') IS NULL THEN 'AVY-SRV-GEN-'||printf('%03d',(SELECT n FROM allocation WHERE allocation.id=commercial_catalog_codes.id)) ELSE sku END,accounting_code=CASE WHEN NULLIF(trim(accounting_code),'') IS NULL THEN 'AVS'||printf('%03d',(SELECT n FROM allocation WHERE allocation.id=commercial_catalog_codes.id)) ELSE accounting_code END,updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE id IN(SELECT id FROM allocation);
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<2*(SELECT count(*)+50 FROM commercial_catalog_codes)), free AS (SELECT n,row_number() OVER(ORDER BY n) rn FROM seq WHERE NOT EXISTS(SELECT 1 FROM commercial_catalog_codes WHERE accounting_code='AVD'||printf('%04d',n) OR sku GLOB 'AVY-DIG-*-'||printf('%04d',n))), missing AS (SELECT id,row_number() OVER(ORDER BY entity_key) rn FROM commercial_catalog_codes WHERE entity_type='product' AND (NULLIF(trim(sku),'') IS NULL OR NULLIF(trim(accounting_code),'') IS NULL)), allocation AS MATERIALIZED (SELECT missing.id,free.n FROM missing JOIN free USING(rn))
UPDATE commercial_catalog_codes SET sku=CASE WHEN NULLIF(trim(sku),'') IS NULL THEN 'AVY-DIG-GEN-'||printf('%04d',(SELECT n FROM allocation WHERE allocation.id=commercial_catalog_codes.id)) ELSE sku END,accounting_code=CASE WHEN NULLIF(trim(accounting_code),'') IS NULL THEN 'AVD'||printf('%04d',(SELECT n FROM allocation WHERE allocation.id=commercial_catalog_codes.id)) ELSE accounting_code END,updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE id IN(SELECT id FROM allocation);
INSERT INTO commercial_catalog_audit(id,catalog_id,actor_user_id,before_json,after_json,created_at)
SELECT 'catalog_0117_'||lower(hex(randomblob(16))),c.id,NULL,CASE WHEN b.id IS NULL THEN NULL ELSE json_object('sku',b.sku,'accounting_code',b.accounting_code) END,json_object('source','catalog_backfill_0117','sku',c.sku,'accounting_code',c.accounting_code),CAST(strftime('%s','now') AS INTEGER)*1000 FROM commercial_catalog_codes c LEFT JOIN _catalog_0117_before b ON b.id=c.id WHERE b.id IS NULL OR c.sku IS NOT b.sku OR c.accounting_code IS NOT b.accounting_code;
DROP TABLE _catalog_0117_before;
